/*
 * hal_sense_poll.c - GENERATED by Polari (board.custom.sense_routes) from the isotope template catoms/sense-led-line/isotopes/gpio-poll/template.c.j2
 * (the catom sense-led-line, isotope gpio-poll), for variant knobs sense_pin=3. No timestamp is written
 * here, so rendering the same knobs again gives the same bytes. EDIT THE TEMPLATE, never this file.
 *
 * It replaces hal.c's INT1 sense block (HAL_SENSE_ROUTE is non-zero, so hal.c skips that block) and supplies the SAME two
 * functions hal.h declares for a sense pin - hal_sense_init / hal_sense_read - so the app (button_clock.c) is unchanged.
 * The sense pin is only ever an INPUT here (it is a wire FROM the LED line, never driven by this build). PLAIN C on avr-libc.
 * cited: DDRD.DDD3 - ATmega328P DS40002061B §14.4.9 DDRD, p.101; §14.2.1 p.85
 * cited: PIND.PIND3 - ATmega328P DS40002061B §14.4.10 PIND, p.101; §14.2.2 p.85
 */

#include <avr/io.h>
#include <stdint.h>

#include "hal.h"

#if !HAL_INT1 || HAL_SENSE_ROUTE != 1
#error "hal_sense_poll.c is the sense route 1 (polled): board_config.h must set HAL_INT1 1 and HAL_SENSE_ROUTE 1"
#endif

/* Everything here runs in the main loop, never in an interrupt, so nothing needs to be volatile or atomic. */
static uint16_t g_sense_rises, g_sense_falls;
static uint32_t g_last_edge_ms;
static uint8_t g_sense_level;               /* the level seen at the last look: 1 = high */

/* D3 = PD3 as a plain input (no pull-up: the pin is a wire from the LED line). The first look is taken here, so the level the
 * line already has at boot is the starting level and not an edge. */
void hal_sense_init(void)
{
    DDRD &= (uint8_t)~_BV(PD3);
    g_sense_level = (PIND & _BV(PD3)) != 0u;
}

/* Called once per main-loop pass: read the pin and, if it differs from the last look, count ONE edge and stamp it. A line that changes twice
 * between two looks is seen as no change (a blink shorter than one pass is missed): that is the cost of this route, and the reason it is
 * only right when the line changes slowly (a person-driven toggle) compared with the loop. */
void hal_sense_read(uint16_t *rises, uint16_t *falls, uint32_t *last_ms)
{
    uint8_t level = (PIND & _BV(PD3)) != 0u;

    if (level != g_sense_level) {
        g_sense_level = level;
        g_last_edge_ms = hal_millis();
        if (level) g_sense_rises++; else g_sense_falls++;
    }
    *rises = g_sense_rises;
    *falls = g_sense_falls;
    *last_ms = g_last_edge_ms;
}
